const $=s=>document.querySelector(s),data=window.wedding;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('#event-grid').innerHTML=data.events.map((e,i)=>`<article class="event-card ${e.featured?'featured':''}"><div class="event-top"><h3>${esc(e.name)}</h3><div class="date-badge"><b>${e.day}</b><span>${e.month}</span></div></div><p class="event-note">${esc(e.note)}</p><p class="event-time">${e.date} 2027<br>${e.time} IST</p><h4>${esc(e.venue)}</h4><p class="address">${esc(e.address)}</p><p class="dress">${esc(e.dress)}</p><div class="event-actions"><a target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(e.address.replace('Sample venue · ',''))}" aria-label="Get directions to ${esc(e.name)} area">Get Directions ↗</a><button data-calendar="${i}">Add to Calendar +</button></div></article>`).join('');
const icsEscape=s=>s.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');
document.querySelectorAll('[data-calendar]').forEach(b=>b.onclick=()=>{const e=data.events[+b.dataset.calendar];const contents=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Arjun Kavya//Wedding//EN','BEGIN:VEVENT',`UID:arjun-kavya-${b.dataset.calendar}@example.com`,'DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z/,'Z'),`DTSTART:${e.start}`,`DTEND:${e.end}`,`SUMMARY:${icsEscape('Arjun & Kavya — '+e.name)}`,`LOCATION:${icsEscape(e.venue+', '+e.address)}`,'DESCRIPTION:Sample wedding event. Confirm final venue with the families.','END:VEVENT','END:VCALENDAR'].join('\r\n');const url=URL.createObjectURL(new Blob([contents],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`arjun-kavya-${e.name.toLowerCase().replace(/ /g,'-')}.ics`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
function countdown(){const total=Math.max(0,Math.floor((new Date(data.ceremony)-Date.now())/1000));const values=[Math.floor(total/86400),Math.floor(total%86400/3600),Math.floor(total%3600/60),total%60];const labels=['DAYS','HOURS','MINUTES','SECONDS'];if(!$('#countdown').children.length)$('#countdown').innerHTML=labels.map(l=>`<div><strong>00</strong><span>${l}</span></div>`).join('');$('#countdown').querySelectorAll('strong').forEach((el,i)=>{let val=String(values[i]).padStart(2,'0');if(el.textContent!==val){el.textContent=val;el.classList.remove('tick');void el.offsetWidth;el.classList.add('tick');}});if(total===0)$('#countdown').setAttribute('aria-label','The wedding day is here');}countdown();setInterval(countdown,1000);
const music=$('#music'),toggle=$('#music-toggle');const remember=(k,v)=>{try{localStorage.setItem(k,v)}catch{}};const recall=k=>{try{return localStorage.getItem(k)}catch{return null}};
music.volume=Math.min(.6,Math.max(0,Number(recall('wedding-volume')??.15)));$('#volume').value=music.volume;
function musicUI(){const on=!music.paused;toggle.setAttribute('aria-pressed',String(on));toggle.setAttribute('aria-label',on?'Pause background music':'Play background music');toggle.innerHTML=`♫ <span>Music ${on?'on':'off'}</span>`;}
async function play(){try{await music.play();remember('wedding-music','on');}catch{$('#audio-status').textContent='Music could not start. Use the music button to try again.';}musicUI();}
toggle.onclick=()=>{if(music.paused)play();else{music.pause();remember('wedding-music','off');musicUI();}};music.addEventListener('pause',musicUI);music.addEventListener('play',musicUI);$('#volume').oninput=e=>{music.volume=Number(e.target.value);remember('wedding-volume',music.volume)};
function openInvitation(withMusic){document.body.classList.add('invitation-open');$('#invitation').classList.add('opened');$('#page').inert=false;if(withMusic)play();else{music.pause();remember('wedding-music','off');}setTimeout(()=>{$('#invitation').hidden=true;$('#invitation').style.display='none';$('.monogram').focus();},1050);if(!matchMedia('(prefers-reduced-motion: reduce)').matches){for(let i=0;i<18;i++){const p=document.createElement('span');p.className='petal';p.textContent='❀';p.style.left=(i%2===0?Math.random()*10:90+Math.random()*10)+'%';p.style.animationDelay=(Math.random()*.7)+'s';$('#petals').append(p);}setTimeout(()=>$('#petals').replaceChildren(),4500);}}
$('#open-music').onclick=()=>openInvitation(true);$('#open-quiet').onclick=()=>openInvitation(false);(recall('wedding-music')==='off'?$('#open-quiet'):$('#open-music')).focus();$('#invitation').addEventListener('keydown',e=>{if(e.key==='Tab'){const first=$('#open-music'),last=$('#open-quiet');if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
$('#gallery-grid').innerHTML=data.gallery.map((p,i)=>`<button data-photo="${i}" aria-label="Enlarge ${esc(p.caption)}"><img src="${p.src}" alt="${esc(p.alt)}" width="600" height="600" loading="lazy"></button>`).join('');let photo=0;const dialog=$('#lightbox');function showPhoto(i){photo=(i+data.gallery.length)%data.gallery.length;const p=data.gallery[photo];$('#large-photo').src=p.src;$('#large-photo').alt=p.alt;$('#photo-caption').textContent=`${photo+1} / ${data.gallery.length} · ${p.caption}`;}
document.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>{showPhoto(+b.dataset.photo);dialog.showModal();document.body.style.overflow='hidden'});function close(){dialog.close();document.body.style.overflow=''}$('#close-gallery').onclick=close;dialog.addEventListener('close',()=>document.body.style.overflow='');$('#prev-photo').onclick=()=>showPhoto(photo-1);$('#next-photo').onclick=()=>showPhoto(photo+1);dialog.addEventListener('keydown',e=>{if(e.key==='ArrowRight')showPhoto(photo+1);if(e.key==='ArrowLeft')showPhoto(photo-1)});dialog.addEventListener('click',e=>{if(e.target===dialog)close()});let touchX=null;dialog.addEventListener('touchstart',e=>touchX=e.changedTouches[0].clientX,{passive:true});dialog.addEventListener('touchend',e=>{if(touchX!==null){const delta=e.changedTouches[0].clientX-touchX;if(Math.abs(delta)>45)showPhoto(photo+(delta<0?1:-1));touchX=null}},{passive:true});


